INSERT INTO `pnae_edital_itens` VALUES ('024ee529-ea52-4479-b8b3-c546b147f253','7975c5be-de6e-4ded-9fa7-f3a932aeafa9','CAFÉ TORRADO E MOÍDO','CAFÉ TORRADO E MOÍDO, torrado e moído, 1ª qualidade, tipo tradicional. Pó homogêneo, aroma e sabor característicos de regular a intenso, isento de grãos pretos, verdes ou fermentados. As características deverão atender aos requisitos mínimos de identidade e qualidade estabelecidos na 250g até 500g, contendo os dados de identificação e procedência, informações nutricionais, número de lote, data de fabricação e data de validade. No ato da entrega o prazo restante de validade deverá ser igual ou superior à metade do período entre a sua data de fabricação e sua data final de validade.',320.00,'KG',73.86,23635.20,NULL,'IMPORTADO',0,'2026-07-08 12:59:16.849','2026-07-08 12:59:16.849',NULL,'importador-editais',NULL,1,18,'torrado e moído, 1ª qualidade, tipo tradicional. Pó homogêneo, aroma e sabor característicos de regular a intenso, isento de grãos pretos, verdes ou fermentados. As características deverão atender aos requisitos mínimos de identidade e qualidade estabelecidos na 250g até 500g, contendo os dados de identificação e procedência, informações nutricionais, número de lote, data de fabricação e data de validade. No ato da entrega o prazo restante de validade deverá ser igual ou superior à metade do período entre a sua data de fabricação e sua data final de validade.'),('0408738a-03fe-4abd-9f3c-08c214c54835','7975c5be-de6e-4ded-9fa7-f3a932aeafa9','ABACAXI PÉROLA','ABACAXI PÉROLA, pérola, inteiro, livre de sujidades, insetos, não se apresentar desidratado, murcho ou congelado. Consistência firme, cascas intactas, de forma que não deixem exposta a polpa, em grau de maturação adequado para consumo, não se apresentar excessivamente maduro ou passado. Acondicionada em saco plástico atóxico, transparente e resistente ou em caixa plástica hortifrúti/vazada.',633.00,'KG',11.29,7146.57,NULL,'IMPORTADO',0,'2026-07-08 12:59:16.849','2026-07-08 12:59:16.849',NULL,'importador-editais',NULL,1,1,'pérola, inteiro, livre de sujidades, insetos, não se apresentar desidratado, murcho ou congelado. Consistência firme, cascas intactas, de forma que não deixem exposta a polpa, em grau de maturação adequado para consumo, não se apresentar excessivamente maduro ou passado. Acondicionada em saco plástico atóxico, transparente e resistente ou em caixa plástica hortifrúti/vazada.'),('054218d4-f2ef-43da-9b8b-6b782ae34bd8','41d63feb-a31a-4998-9cf7-798149a10fc5','BOLO DE COCO','BOLO DE COCO, caseiro, confeccionado de forma artesanal através da mistura de farinha de trigo, ovos, óleo vegetal, açúcar, químico, adicionado de fermento químico, sem adição de conservantes químicos. Entregue em embalagens plásticas ou formas de alumínio, devidamente acondicionadas, garantindo condições higiênico-sanitárias adequadas. Livre de sujidades, insetos, mofo e bolor. Não podendo ser obtido de mistura industrializada.',92.00,'KG',29.80,2741.60,NULL,'IMPORTADO',0,'2026-07-08 12:59:16.508','2026-07-08 12:59:16.508',NULL,'importador-editais',NULL,1,15,'caseiro, confeccionado de forma artesanal através da mistura de farinha de trigo, ovos, óleo vegetal, açúcar, químico, adicionado de fermento químico, sem adição de conservantes químicos. Entregue em embalagens plásticas ou formas de alumínio, devidamente acondicionadas, garantindo condições higiênico-sanitárias adequadas. Livre de sujidades, insetos, mofo e bolor. Não podendo ser obtido de mistura industrializada.'),('05c4794d-d9f3-4ee8-870e-12706fef9040','a24222a9-33a3-4107-ac3f-aecc93ac64a8','FARINHA DE MILHO','FARINHA DE MILHO, SEM GLÚTEN. Produto de coloração amarela, com aspecto, cor, cheiro e sabor próprios, com ausência de umidade, isento de sujidade, parasitas e larvas. As características de qualidade e identidade do produto deverão estar de acordo com a legislação vigente. Embalagem de polietileno atóxico, resistente podendo ser transparente ou não, contendo externamente os da